public class DOMNodePointer_findEnclosingAttribute_TriageGen2Test {

    /**
     * Helper method to access the protected static method via reflection.
     */
    @SuppressWarnings("unchecked")
    private String invokeFindEnclosingAttribute(Node n, String attrName) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("findEnclosingAttribute", Node.class, String.class);
        method.setAccessible(true);
        return (String) method.invoke(null, n, attrName);
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        assertNull(invokeFindEnclosingAttribute(null, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_NonElementNode_ReturnsNull() throws Exception {
        Node textNode = mock(Node.class);
        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(textNode, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithEmptyAttribute_MovesToParent() throws Exception {
        // Create hierarchy: Parent (attr="val") -> Child (attr="")
        Element parent = mock(Element.class);
        Element child = mock(Element.class);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("val");
        when(parent.getParentNode()).thenReturn(null);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn(""); // Empty string case
        when(child.getParentNode()).thenReturn(parent);

        assertEquals("val", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_ElementWithNullAttribute_MovesToParent() throws Exception {
        Element parent = mock(Element.class);
        Element child = mock(Element.class);

        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("val");
        when(parent.getParentNode()).thenReturn(null);

        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn(null); // Null case
        when(child.getParentNode()).thenReturn(parent);

        assertEquals("val", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_FoundOnImmediateNode() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("target")).thenReturn("found");
        when(element.getParentNode()).thenReturn(null);

        assertEquals("found", invokeFindEnclosingAttribute(element, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_FoundOnGrandparent() throws Exception {
        Element grandparent = mock(Element.class);
        Element parent = mock(Element.class);
        Element child = mock(Element.class);

        // Grandparent setup
        when(grandparent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(grandparent.getAttribute("target")).thenReturn("grandparentVal");
        when(grandparent.getParentNode()).thenReturn(null);

        // Parent setup
        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn(""); 
        when(parent.getParentNode()).thenReturn(grandparent);

        // Child setup
        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn(null);
        when(child.getParentNode()).thenReturn(parent);

        assertEquals("grandparentVal", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_TraverseThroughNonElementNodes() throws Exception {
        Element element = mock(Element.class);
        Node textNode = mock(Node.class);
        Element parent = mock(Element.class);

        // Parent setup
        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("targetVal");
        when(parent.getParentNode()).thenReturn(null);

        // Text Node setup
        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);
        when(textNode.getParentNode()).thenReturn(parent);

        // Element setup
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("target")).thenReturn(null);
        when(element.getParentNode()).thenReturn(textNode);

        assertEquals("targetVal", invokeFindEnclosingAttribute(element, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_NoAttributeFoundInHierarchy() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("missing")).thenReturn("");
        when(element.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(element, "missing"));
    }
}
